package com.feedback.surveys.controller;

import com.feedback.surveys.repository.ReactiveSurveyResponseRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Mono;

@RestController
@RequestMapping("/surveys/responses")
public class SurveyReactiveController {

    private final ReactiveSurveyResponseRepository responseRepository;

    public SurveyReactiveController(ReactiveSurveyResponseRepository responseRepository) {
        this.responseRepository = responseRepository;
    }

    @PatchMapping("/{responseId}/rate")
    public Mono<ResponseEntity<String>> adjustFeedbackRating(
            @PathVariable Long responseId,
            @RequestParam int rating,
            Authentication authentication) {
        return responseRepository.findById(responseId)
                .flatMap(response -> {
                    if (!response.getRespondentId().equals(authentication.getName())) {
                        return Mono.error(new AccessDeniedException("Cannot alter ratings of other respondents"));
                    }
                    response.setScore(rating);
                    return responseRepository.save(response);
                })
                .map(saved -> ResponseEntity.ok("Rating updated"))
                .defaultIfEmpty(ResponseEntity.notFound().build());
    }
}
